import React from "react";
import "./home.css";
import Blurred from "./mainhome/blurredlist";
const LazyRoomCarts = React.lazy(() => import("./roomcarts"));
const LazyFoodCarts = React.lazy(() => import("./foodcards"));

const Home = () => {
  return (
    <>
      <div id="carouselExampleFade" class="carousel slide carousel-fade" data-bs-ride="carousel">
        <div class="carousel-inner">
          <div class="carousel-item active">
            <img src="https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRJroBbs891B1m89zj53_ZA2g6NUtDLmgAwVg&s" class="d-block w-100" alt="Images" />
          </div>
          <div class="carousel-item">
            <img src="https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSFbLyNx9trKNSMOjTAXXkTj5xfRQg5YIcZ9A&s" class="d-block w-100" alt="Images" />
          </div>
          <div class="carousel-item">
            <img src="https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRjSDg9gpUUEtwi5zp0Xz6BXxGys8XJLseLaQ&s" class="d-block w-100" alt="Images" />
          </div>
        </div>
        <button class="carousel-control-prev" type="button" data-bs-target="#carouselExampleFade" data-bs-slide="prev">
          <span class="carousel-control-prev-icon" aria-hidden="true"></span>
          <span class="visually-hidden">Previous</span>
        </button>
        <button class="carousel-control-next" type="button" data-bs-target="#carouselExampleFade" data-bs-slide="next">
          <span class="carousel-control-next-icon" aria-hidden="true"></span>
          <span class="visually-hidden">Next</span>
        </button>
      </div>
    </>
  );
};

export default Home;
